34	/**
35	 * Simple JavaBean domain object representing an owner.
36	 *
37	 * @author Ken Krebs
38	 * @author Juergen Hoeller
39	 * @author Sam Brannen
40	 * @author Michael Isvy
41	 */
42	@Entity
43	@Table(name = "owners")
44	public class Owner extends Person {
45	    @Column(name = "address")
46	    @NotEmpty
47	    private String address;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "telephone")
54	    @NotEmpty
55	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
56	    private String telephone;
57	
58	    @Column(name = "email")
59	    private String email;
60	
61	    @Column(name = "postcode")
62	    private String postcode;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "customer_code")
71	    private String customerCode;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "household_size")
80	    private Integer householdSize;
81	
82	    @Column(name = "membership_number")
83	    private String membershipNumber;
84	
85	    @Column(name = "bulk_signup_warning", nullable = false)
86	    private boolean bulkSignupWarning;
87	
88	    @Column(name = "possible_duplicate", nullable = false)
89	    private boolean possibleDuplicate;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
95	    private Set<Pet> pets;
96	
97	    public String getAddress() {
98	        return this.address;
99	    }
100	
101	    public void setAddress(String address) {
102	        this.address = address;
103	    }
104	
105	    public String getCity() {
106	        return this.city;
107	    }
108	
109	    public void setCity(String city) {
110	        this.city = city;
111	    }
112	
113	    public String getTelephone() {
114	        return this.telephone;
115	    }
116	
117	    public void setTelephone(String telephone) {
118	        this.telephone = telephone;
119	    }
120	
121	    /**
122	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
123	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
124	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
125	     * persisted.
126	     */
127	    public String getTelephoneDisplay() {
128	        return E164PhoneNumber.toDisplay(this.telephone);
129	    }
130	
131	    public String getEmail() {
132	        return this.email;
133	    }
134	
135	    public void setEmail(String email) {
136	        this.email = email;
137	    }
138	
139	    /**
140	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
141	     * against the city's region and then stored verbatim. Optional, so may be null.
142	     */
143	    public String getPostcode() {
144	        return this.postcode;
145	    }
146	
147	    public void setPostcode(String postcode) {
148	        this.postcode = postcode;
149	    }
150	
151	    public LocalDate getRegistrationDate() {
152	        return this.registrationDate;
153	    }
154	
155	    public void setRegistrationDate(LocalDate registrationDate) {
156	        this.registrationDate = registrationDate;
157	    }
158	
159	    /**
160	     * The owner's date of birth. Optional, so may be null.
161	     */
162	    public LocalDate getBirthDate() {
163	        return this.birthDate;
164	    }
165	
166	    public void setBirthDate(LocalDate birthDate) {
167	        this.birthDate = birthDate;
168	    }
169	
170	    /**
171	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
172	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
173	     * birth date against the registration date. Null when no birth date is recorded.
174	     * Derived from stored state, never persisted.
175	     */
176	    public String getAgeBand() {
177	        if (this.birthDate == null || this.registrationDate == null) {
178	            return null;
179	        }
180	        return AgeBand.of(this.birthDate, this.registrationDate);
181	    }
182	
183	    public String getCustomerCode() {
184	        return this.customerCode;
185	    }
186	
187	    public void setCustomerCode(String customerCode) {
188	        this.customerCode = customerCode;
189	    }
190	
191	    /**
192	     * The stable identifier of the household this owner belongs to: the first twelve hex
193	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
194	     * sharing a last name and postcode resolves to the same value. Null when the owner has
195	     * no postcode. Assigned at creation.
196	     */
197	    public String getHouseholdId() {
198	        return this.householdId;
199	    }
200	
201	    public void setHouseholdId(String householdId) {
202	        this.householdId = householdId;
203	    }
204	
205	    public Integer getNamesakeCount() {
206	        return this.namesakeCount;
207	    }
208	
209	    public void setNamesakeCount(Integer namesakeCount) {
210	        this.namesakeCount = namesakeCount;
211	    }
212	
213	    public Integer getHouseholdSize() {
214	        return this.householdSize;
215	    }
216	
217	    public void setHouseholdSize(Integer householdSize) {
218	        this.householdSize = householdSize;
219	    }
220	
221	    public String getMembershipNumber() {
222	        return this.membershipNumber;
223	    }
224	
225	    public void setMembershipNumber(String membershipNumber) {
226	        this.membershipNumber = membershipNumber;
227	    }
228	
229	    /**
230	     * Whether this owner was created as part of a bulk signup: {@code true} when more
231	     * than 80 owners had already been registered on this owner's registration date at
232	     * the moment it was created, {@code false} otherwise. Captured at creation.
233	     */
234	    public boolean isBulkSignupWarning() {
235	        return this.bulkSignupWarning;
236	    }
237	
238	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
239	        this.bulkSignupWarning = bulkSignupWarning;
240	    }
241	
242	    /**
243	     * Whether this owner resembles an existing one: {@code true} when, at creation, it
244	     * shared an existing owner's household (same last name and postcode, hence the same
245	     * {@link #getHouseholdId() household id}) while having a different telephone and was not
246	     * a declared household member, {@code false} otherwise. A declared member (created with
247	     * {@code sharesHousehold}) is a genuine member, not a suspected duplicate. When true,
248	     * {@link #getPossibleDuplicateOf()} holds that owner's id. Captured at creation.
249	     */
250	    public boolean isPossibleDuplicate() {
251	        return this.possibleDuplicate;
252	    }
253	
254	    public void setPossibleDuplicate(boolean possibleDuplicate) {
255	        this.possibleDuplicate = possibleDuplicate;
256	    }
257	
258	    /**
259	     * The id of the existing owner this owner possibly duplicates (same household — last
260	     * name and postcode — different telephone), or null when it is not a possible
261	     * duplicate. Captured at creation.
262	     */
263	    public Integer getPossibleDuplicateOf() {
264	        return this.possibleDuplicateOf;
265	    }
266	
267	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
268	        this.possibleDuplicateOf = possibleDuplicateOf;
269	    }
270	
271	    /**
272	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
273	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
274	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
275	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
276	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
277	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
278	     * region is derived directly from the stored postcode and city. Derived from stored
279	     * state, never persisted.
280	     */
281	    public String getLocality() {
282	        String region = CustomerCode.regionOf(this.customerCode);
283	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
284	    }
285	
286	    /**
287	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
288	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
289	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
290	     * has no known timezone. Derived from stored state, never persisted.
291	     */
292	    public String getTimezone() {
293	        return RegionTimezone.forRegion(getLocality());
294	    }
295	
296	    /**
297	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
298	     * has an email address, gains 1 when this owner had no namesakes at creation
299	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
300	     * members, and gains 3 when this owner's tenure exceeds 365 days. A newly created owner
301	     * has zero tenure, so it never earns those points at creation. Derived from stored
302	     * state, never persisted.
303	     */
304	    public int getMembershipPoints() {
305	        int points = 0;
306	        if (hasEmail()) {
307	            points += 2;
308	        }
309	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
310	            points += 1;
311	        }
312	        if (this.householdSize != null && this.householdSize >= 3) {
313	            points += 2;
314	        }
315	        if (getTenureDays() > 365) {
316	            points += 3;
317	        }
318	        return points;
319	    }
320	
321	    /**
322	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
323	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Derived from
324	     * stored state, never persisted.
325	     */
326	    public int getMembershipLevel() {
327	        int points = getMembershipPoints();
328	        if (points <= 1) {
329	            return 1;
330	        }
331	        if (points <= 3) {
332	            return 2;
333	        }
334	        if (points <= 5) {
335	            return 3;
336	        }
337	        return 4;
338	    }
339	
340	    /**
341	     * The owner's tenure in whole days: the number of days from the {@code registrationDate}
342	     * to the current server date, or 0 when no registration date is recorded. Never negative
343	     * in practice, since a future registration date is rejected at creation.
344	     */
345	    private long getTenureDays() {
346	        if (this.registrationDate == null) {
347	            return 0;
348	        }
349	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
350	    }
351	
352	    /**
353	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
354	     * the {@code customerCode}. Derived from stored state, never persisted.
355	     */
356	    public int getCheckDigit() {
357	        return LuhnCheckDigit.of(this.customerCode);
358	    }
359	
360	    /**
361	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
362	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
363	     */
364	    public String getContactPreference() {
365	        return hasEmail() ? "EMAIL" : "PHONE";
366	    }
367	
368	    /**
369	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
370	     * the email (or empty when absent) and the household id (or empty when none), joined by
371	     * {@code '|'}. Derived from stored state, never persisted.
372	     */
373	    public String getIdentityKey() {
374	        String emailPart = hasEmail() ? this.email : "";
375	        String householdPart = this.householdId == null ? "" : this.householdId;
376	        return this.telephone + "|" + emailPart + "|" + householdPart;
377	    }
378	
379	    private boolean hasEmail() {
380	        return this.email != null && !this.email.isEmpty();
381	    }
382	
383	    protected Set<Pet> getPetsInternal() {
384	        if (this.pets == null) {
385	            this.pets = new HashSet<>();
386	        }
387	        return this.pets;
388	    }
389	
390	    protected void setPetsInternal(Set<Pet> pets) {
391	        this.pets = pets;
392	    }
393	
394	    public List<Pet> getPets() {
395	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
396	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
397	        return Collections.unmodifiableList(sortedPets);
398	    }
399	
400	    public void setPets(List<Pet> pets) {
401	        this.pets = new HashSet<>(pets);
402	    }
403	
404	    public void addPet(Pet pet) {
405	        getPetsInternal().add(pet);
406	        pet.setOwner(this);
407	    }
408	
409	    /**
410	     * Return the Pet with the given name, or null if none found for this Owner.
411	     *
412	     * @param name to test
413	     * @return true if pet name is already in use
414	     */
415	    public Pet getPet(String name) {
416	        return getPet(name, false);
417	    }
418	
419	    /**
420	     * Return the Pet with the given name, or null if none found for this Owner.
421	     *
422	     * @param name to test
423	     * @return true if pet name is already in use
424	     */
425	    public Pet getPet(String name, boolean ignoreNew) {
426	        name = name.toLowerCase();
427	        for (Pet pet : getPetsInternal()) {
428	            if (!ignoreNew || !pet.isNew()) {
429	                String compName = pet.getName();
430	                compName = compName.toLowerCase();
431	                if (compName.equals(name)) {
432	                    return pet;
433	                }
434	            }
435	        }
436	        return null;
437	    }
438	
439	    public Pet getPet(Integer petId) {
440	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
441	    }
442	
443	    @Override
444	    public String toString() {
445	        return new ToStringCreator(this)
446	
447	            .append("id", this.getId())
448	            .append("new", this.isNew())
449	            .append("lastName", this.getLastName())
450	            .append("firstName", this.getFirstName())
451	            .append("address", this.address)
452	            .append("city", this.city)
453	            .append("telephone", this.telephone)
454	            .toString();
455	    }
456	}
