1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Normalizes a postal address to a single canonical form: leading and trailing whitespace
8	 * is trimmed, internal runs of whitespace collapse to one space, the text is upper-cased,
9	 * and common street-type abbreviations are expanded to their full word.
10	 *
11	 * <p>So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and {@code "7 elm ave"}
12	 * becomes {@code "7 ELM AVENUE"}. An input that is {@code null} or blank normalizes to the
13	 * empty string.
14	 */
15	public final class AddressNormalizer {
16	
17	    /** Street-type abbreviations expanded to their full word (compared per whole token). */
18	    private static final Map<String, String> ABBREVIATIONS = Map.of(
19	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
20	
21	    private AddressNormalizer() {
22	    }
23	
24	    /**
25	     * @param raw the caller-supplied address, in any casing and spacing
26	     * @return the canonical address, or the empty string when {@code raw} is null or blank
27	     */
28	    public static String normalize(String raw) {
29	        if (raw == null || raw.isBlank()) {
30	            return "";
31	        }
32	        String[] tokens = raw.trim().toUpperCase(Locale.ROOT).split("\\s+");
33	        StringBuilder sb = new StringBuilder(raw.length());
34	        for (String token : tokens) {
35	            if (sb.length() > 0) {
36	                sb.append(' ');
37	            }
38	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
39	        }
40	        return sb.toString();
41	    }
42	}
