271	    /**
272	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
273	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
274	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
275	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
276	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
277	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
278	     * region is derived directly from the stored postcode and city. Derived from stored
279	     * state, never persisted.
280	     */
281	    public String getLocality() {
282	        String region = CustomerCode.regionOf(this.customerCode);
283	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
284	    }
