296	    /**
297	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
298	     * has an email address, gains 1 when this owner had no namesakes at creation
299	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
300	     * members, and gains 3 when this owner's tenure exceeds 365 days. A newly created owner
301	     * has zero tenure, so it never earns those points at creation. Derived from stored
302	     * state, never persisted.
303	     */
304	    public int getMembershipPoints() {
305	        int points = 0;
306	        if (hasEmail()) {
307	            points += 2;
308	        }
309	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
310	            points += 1;
311	        }
312	        if (this.householdSize != null && this.householdSize >= 3) {
313	            points += 2;
314	        }
315	        if (getTenureDays() > 365) {
316	            points += 3;
317	        }
318	        return points;
319	    }
320	
321	    /**
322	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
323	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Derived from
324	     * stored state, never persisted.
325	     */
326	    public int getMembershipLevel() {
327	        int points = getMembershipPoints();
328	        if (points <= 1) {
329	            return 1;
330	        }
331	        if (points <= 3) {
332	            return 2;
333	        }
334	        if (points <= 5) {
335	            return 3;
336	        }
337	        return 4;
338	    }
339	
340	    /**
341	     * The owner's tenure in whole days: the number of days from the {@code registrationDate}
342	     * to the current server date, or 0 when no registration date is recorded. Never negative
343	     * in practice, since a future registration date is rejected at creation.
344	     */
345	    private long getTenureDays() {
346	        if (this.registrationDate == null) {
347	            return 0;
348	        }
349	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
350	    }
351	
352	    /**
353	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
354	     * the {@code customerCode}. Derived from stored state, never persisted.
355	     */
356	    public int getCheckDigit() {
357	        return LuhnCheckDigit.of(this.customerCode);
358	    }
359	
360	    /**
361	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
362	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
363	     */
364	    public String getContactPreference() {
365	        return hasEmail() ? "EMAIL" : "PHONE";
366	    }
367	
368	    /**
369	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
370	     * the email (or empty when absent) and the household id (or empty when none), joined by
371	     * {@code '|'}. Derived from stored state, never persisted.
372	     */
373	    public String getIdentityKey() {
374	        String emailPart = hasEmail() ? this.email : "";
375	        String householdPart = this.householdId == null ? "" : this.householdId;
376	        return this.telephone + "|" + emailPart + "|" + householdPart;
377	    }
378	
379	    private boolean hasEmail() {
380	        return this.email != null && !this.email.isEmpty();
381	    }
382	
383	    protected Set<Pet> getPetsInternal() {
384	        if (this.pets == null) {
385	            this.pets = new HashSet<>();
386	        }
387	        return this.pets;
388	    }
389	
390	    protected void setPetsInternal(Set<Pet> pets) {
391	        this.pets = pets;
392	    }
393	
394	    public List<Pet> getPets() {
395	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
396	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
397	        return Collections.unmodifiableList(sortedPets);
398	    }
399	
400	    public void setPets(List<Pet> pets) {
401	        this.pets = new HashSet<>(pets);
402	    }
403	
404	    public void addPet(Pet pet) {
405	        getPetsInternal().add(pet);
406	        pet.setOwner(this);
407	    }
408	
409	    /**
410	     * Return the Pet with the given name, or null if none found for this Owner.
411	     *
412	     * @param name to test
413	     * @return true if pet name is already in use
414	     */
415	    public Pet getPet(String name) {
416	        return getPet(name, false);
417	    }
418	
419	    /**
420	     * Return the Pet with the given name, or null if none found for this Owner.
421	     *
422	     * @param name to test
423	     * @return true if pet name is already in use
424	     */
425	    public Pet getPet(String name, boolean ignoreNew) {
426	        name = name.toLowerCase();
427	        for (Pet pet : getPetsInternal()) {
428	            if (!ignoreNew || !pet.isNew()) {
429	                String compName = pet.getName();
430	                compName = compName.toLowerCase();
431	                if (compName.equals(name)) {
432	                    return pet;
433	                }
434	            }
435	        }
436	        return null;
437	    }
438	
439	    public Pet getPet(Integer petId) {
440	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
441	    }
442	
443	    @Override
444	    public String toString() {
445	        return new ToStringCreator(this)
446	
447	            .append("id", this.getId())
448	            .append("new", this.isNew())
449	            .append("lastName", this.getLastName())
450	            .append("firstName", this.getFirstName())
451	            .append("address", this.address)
452	            .append("city", this.city)
453	            .append("telephone", this.telephone)
454	            .toString();
455	    }
456	}
