9	/**
10	 * Validates an owner request's optional postcode: absent or blank is left untouched
11	 * (the field is optional and the contract stays backward-compatible). When present it
12	 * must be four digits and, for a city in a known region, fall within that region's
13	 * range; otherwise the request is rejected with a 400. A city with no known region
14	 * accepts any 4-digit postcode. The value is stored verbatim, so nothing is mutated.
15	 */
16	public class ValidateOwnerPostcode {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
19	        String postcode = request.getPostcode();
20	        if (postcode == null || postcode.isBlank()) {
21	            return;
22	        }
23	        if (!Postcodes.hasValidFormat(postcode)) {
24	            throw new InvalidPostcodeException(postcode, "must be four digits");
25	        }
26	        String region = CityLocality.forCity(request.getCity());
27	        if (!Postcodes.isAllowedForRegion(region, postcode)) {
28	            throw new InvalidPostcodeException(postcode,
29	                    "outside the postcode range for region " + region);
30	        }
31	    }
