3	import java.util.Objects;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.util.CityLocality;
11	import org.springframework.samples.petclinic.util.CustomerCode;
12	import org.springframework.samples.petclinic.util.Sha256;
13	
14	/**
15	 * Assigns the new owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}: the
16	 * canonical region derived from the postcode (falling back to the city, see
17	 * {@link CityLocality}), a hyphen, and the first eight upper-case hex characters of the
18	 * SHA-256 of the normalized telephone concatenated with the last name (e.g.
19	 * {@code NSW-1A2B3C4D}). Should the composed code collide with an existing owner's, it is
20	 * de-duplicated with a {@code -<n>} suffix (see {@link CustomerCode#deduplicate}). Runs
21	 * after {@link BuildOwner} (so the entity, its postcode, telephone and last name exist)
22	 * and before {@link SaveOwner} persists the code.
23	 */
24	public class AssignOwnerCustomerCode {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String region = CityLocality.forPostcodeOrCity(owner.getPostcode(), owner.getCity());
28	        String hash8 = Sha256.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
29	        String code = CustomerCode.of(region, hash8);
30	        Set<String> existing = ownerRepository.findAll().stream()
31	                .map(Owner::getCustomerCode)
32	                .filter(Objects::nonNull)
33	                .collect(Collectors.toSet());
34	        owner.setCustomerCode(CustomerCode.deduplicate(code, existing));
35	    }
36	}
